window.AUTH=window.AUTH||{};window.AUTH["21-1086"]={"d":"21-1086","id":"2022/21-1086","n":"Allen v. Milligan","briefs":[{"k":"petitioner","label":"Brief of appellants/petitioners John H. Merrill, Alabama Secretary of State, et al.","date":"2022-04-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/221827/20220425152045101_Milligan%20-%20Merits%20Br%20FINAL%204-25.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of respondents Marcus Caster, et al.","date":"2022-07-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/229762/20220711135711406_2022-07-11%20Caster%20Merits%20Brief%20Final.pdf","side":"res","n":51},{"k":"respondent","label":"Brief of appellees Evan Milligan, et al.","date":"2022-07-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/229773/20220711132550198_2022.07.11%20Milligan%20Br.%20for%20Appellees_A.pdf","side":"res","n":65},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-07-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/230317/20220718201827432_21-1086bsacUnitedStates.pdf","side":"us","n":41},{"k":"reply","label":"Reply of appellants/petitioners John H. Merrill, Alabama Secretary of State, et al.","date":"2022-08-24","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/234404/20220824160744143_Merrill%20-%20Merits%20Reply%20Brief%20FINAL.pdf","side":"pet","n":49}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r33_dc8f.pdf","tr":true,"items":[{"t":"case","label":"Abbott v. Perez","cite":"138 S. Ct. 2305","y":2018,"id":"2017/17-586","sc":1,"sum":"The Court decided that the district court erred in disregarding the presumption of good faith on the part of the Texas Legislature and improperly reversed the burden of proof in requiring the state to show a lack of discriminatory intent in adopting new districting plans; the Court also held that one of the state house districts at issue was an impermissible racial gerrymander.","sumSrc":"Oyez","by":{"0":"38, 42","1":"45","2":"25, 32, 48, 52","3":"13, 14, 17, 21","4":"24, 25"}},{"t":"case","label":"Abrams v. Johnson","cite":"521 U.S. 74","y":1997,"id":"1996/95-1425","sc":1,"op":8,"ar":3,"sum":"First, the Court held that in re-drafting the plans, the District Court had no obligation to preserve all three of the old plan's black-majority districts, if this would result in racial gerrymandering. Second, the Court supported the District Court's decision not to preserve two black-majority districts as it held that the area's black population was not sufficiently compact to sustain such a plan.","sumSrc":"Oyez","by":{"0":"passim","2":"28, 56","4":"16"}},{"t":"case","label":"Ala. Legis. Black Caucus v. Alabama","cite":"575 U.S. 254","y":2015,"id":"2014/13-895","sc":1,"op":4,"sum":"The Court held that states may not substitute their own extraneous goals for the traditional goals of the Voting Rights Act of 1965 when redrawing electoral districts.","sumSrc":"Oyez","by":{"0":"39","1":"54","2":"39, 42"}},{"t":"case","label":"Bartlett v. Strickland","cite":"556 U.S. 1","y":2009,"id":"2008/07-689","sc":1,"op":6,"ar":5,"sum":"The Court found that the Voting Rights Act of 1965 did not require redistricting in a county lacking a numerical majority of a racial minority of citizens.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"27, 45, 46, 52","3":"12, 14, 15, 23, 28, 34","4":"passim"}},{"t":"case","label":"Bethune-Hill v. Va. State Bd. of Elections","cite":"137 S. Ct. 788","y":2017,"id":"2016/15-680","sc":1,"op":15,"ar":4,"sum":"The Court determined that race can be shown to be the predominant factor in redistricting even when traditional principles are respected, and that district courts must engage in a holistic analysis.","sumSrc":"Oyez","by":{"0":"passim","1":"55","3":"25, 26","4":"13, 28"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"op":16,"ar":6,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","2":"34","3":"2, 3, 5, 11, 23, 31","4":"passim"}},{"t":"case","label":"Bush v. Vera","cite":"517 U.S. 952","y":1996,"id":"1995/94-805","sc":1,"op":13,"ar":1,"sum":"In a 5-to-4 decision, the Court held that the Texas redistricting plans were unconstitutional. Supporting its \"strict scrutiny\" approach, the Court noted that the proposed districts were highly irregular in shape, that their computerized design was significantly more sensitive to racial data, and that they lacked any semblance to pre-existing race-neutral districts.","sumSrc":"Oyez","by":{"0":"passim","1":"35","2":"27, 33, 51, 52, 53, 57","3":"17, 25, 26","4":"1, 16, 24"}},{"t":"case","label":"City of Boerne v. Flores","cite":"521 U.S. 507","y":1997,"id":"1996/95-2074","sc":1,"op":7,"sum":"The Court ruled that Congress exceeded its Fourteenth Amendment powers when it enacted the Religious Freedom Restoration Act, subjecting local ordinance to federal regulation.","sumSrc":"Oyez","by":{"0":"73, 75","1":"57, 59","2":"56, 57"}},{"t":"case","label":"City of Mobile v. Bolden","cite":"446 U.S. 55","y":1980,"id":"1978/77-1844","sc":1,"op":21,"ar":11,"sum":"The Court held that the Fifteenth Amendment did not entail \"the right to have Negro candidates elected,\" and that only purposefully discriminatory denials of the freedom to vote on the basis of race demanded constitutional remedies.","sumSrc":"Oyez","by":{"0":"5, 6, 73, 74","1":"5, 44","2":"4","3":"2, 9, 20"}},{"t":"case","label":"Cooper v. Harris","cite":"137 S. Ct. 1455","y":2017,"id":"2016/15-1262","sc":1,"sum":"The Court determined that the district court did not error in determining that North Carolina’s new districting plan constituted an unconstitutional racial gerrymander, and neither claim nor issue preclusion based on the state court case dictate the outcome of this case.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"14, 28, 30, 52","3":"21, 25, 27, 33","4":"20, 24, 29"}},{"t":"case","label":"Davis v. Bandemer","cite":"478 U.S. 109","y":1986,"id":"1985/84-1244","sc":1,"op":14,"sum":"The Court held that while the apportionment law may have had a discriminatory effect on the Democrats, that effect was not \"sufficiently adverse\" to violate the Equal Protection Clause. The mere lack of proportional representation did not unconstitutionally diminish the Democrats' electoral power.","sumSrc":"Oyez","by":{"0":"41, 64"}},{"t":"case","label":"Georgia v. Ashcroft","cite":"539 U.S. 461","y":2003,"id":"2002/02-182","sc":1,"op":6,"ar":5,"sum":"The Court held that the District Court failed to consider all the relevant factors when it examined whether Georgia's Senate plan resulted in a retrogression of black voters' effective exercise of the electoral franchise.","sumSrc":"Oyez","by":{"0":"49, 69","1":"44","4":"4, 26"}},{"t":"case","label":"Gonzalez v. City of Aurora","cite":"535 F.3d 594","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/535/594/","op":2,"by":{"0":"passim","3":"28, 29","4":"5, 30, 31, 32"}},{"t":"case","label":"Growe v. Emison","cite":"507 U.S. 25","y":1993,"id":"1992/91-1420","sc":1,"op":12,"sum":"Shortly after a group of Minnesota voters filed a state-court action against the Minnesota Secretary of State and other election officials, appellee voters filed a similar action against essentially the same officials in the Federal District Court. Both suits alleged that, in light of the 1990 census results, the State's congressional and legislative districts were malapportioned, in violation of the Federal and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"49, 51","2":"26, 27","3":"5, 12, 14, 30","4":"25"}},{"t":"case","label":"Harris v. McCrory","cite":"159 F. Supp. 3d 600","y":2016,"court":"M.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/159/600/","by":{"0":"68, 78"}},{"t":"case","label":"Holder v. Hall","cite":"512 U.S. 874","y":1994,"id":"1993/91-2012","sc":1,"op":28,"sum":"Explaining that single-member districts may provide the benchmark when multimember or at-large systems are challenged, but suggesting no benchmark for challenges to single-member districts.","sumSrc":"opinion","by":{"0":"passim","1":"50, 51","3":"31"}},{"t":"case","label":"Johnson v. De Grandy","cite":"512 U.S. 997","y":1994,"id":"1993/92-519","sc":1,"op":28,"ar":3,"sum":"Noting the “general agreement” on this point.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"29, 39, 40, 53","3":"14, 19, 21, 22","4":"passim"}},{"t":"case","label":"Karcher v. Daggett","cite":"462 U.S. 725","y":1983,"id":"1982/81-2057","sc":1,"op":1,"ar":1,"sum":"Explaining that residents of a political unit “often develop a community of interest”.","sumSrc":"opinion","by":{"0":"61","4":"22"}},{"t":"case","label":"Lawyer v. Dep’t of Justice","cite":"521 U.S. 567","y":1997,"id":"1996/95-2024","sc":1,"op":6,"sum":"The Court held that the State exercised the choice to which it was entitled under our cases, that Lawyer had no right to block the settlement, and that he failed to point out any unconstitutionality in the proposed plan.","sumSrc":"Oyez","by":{"0":"43","2":"32, 44, 47"}},{"t":"case","label":"League of United Latin Am. Citizens v. Perry","cite":"548 U.S. 399","y":2006,"id":"2005/05-204","sc":1,"op":10,"sum":"The Supreme Court held that the Texas Legislature's redistricting plan did not violate the Constitution, but that part of the plan violated the Voting Rights Act. Justice Anthony Kennedy, writing for a majority of the justices, stated that District 23 had been redrawn in such a way as to deny Latino voters as a group the opportunity to elect a candidate of their choosing, thereby violating the Voting Rights Act.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","3":"12, 14, 16, 17, 22","4":"passim"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"op":10,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"Miller v. Johnson","cite":"515 U.S. 900","y":1995,"id":"1994/94-631","sc":1,"op":24,"sum":"Explaining that race predominates when “the [mapmaker] subordinated traditional race-neutral districting principles . . . to racial considerations”.","sumSrc":"opinion","by":{"0":"passim","1":"26, 54, 55, 56","2":"45, 46","3":"25, 33","4":"passim"}},{"t":"case","label":"Miss. Republican Exec. Comm. v. Brooks","cite":"469 U.S. 1002","y":1984,"url":"https://supreme.justia.com/cases/federal/us/469/1002/","sc":1,"op":1,"by":{"0":"7, 33, 73","3":"32","4":"7"}},{"t":"case","label":"Montejo v. Louisiana","cite":"556 U.S. 778","y":2009,"id":"2008/07-1529","sc":1,"op":2,"sum":"The Court held that after the appointment of an attorney, a defendant does not necessarily need to take additional steps to accept the appointment in order to secure the protections of the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"op":2,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"0":"73, 75, 77"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"op":2,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"0":"52","1":"43","2":"41, 42","3":"23"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Rucho v. Common Cause","cite":"139 S. Ct. 2484","y":2019,"id":"2018/18-422","sc":1,"op":5,"sum":"Partisan gerrymandering claims present political questions beyond the reach of the federal courts.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 79","3":"29","4":"19, 22"}},{"t":"case","label":"Shaw v. Hunt","cite":"517 U.S. 907","y":1996,"id":"1995/94-923","sc":1,"op":10,"sum":"In a 5-to-4 opinion by Chief Justice Rehnquist, the Court first confronted the threshold question of \"standing.\" It held that some of the appellants lacked proper standing to challenge the redistricting plan. Only those voters who resided in a congressional district alleged to have been created by racial gerrymandering had proper standing to challenge the constitutionality of that district's creation.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","3":"26, 27","4":"passim"}},{"t":"case","label":"Shaw v. Reno","cite":"509 U.S. 630","y":1993,"id":"1992/92-357","sc":1,"op":13,"sum":"The Court held that the redistricting of North Carolina was evidence of an attempt to separate voters based on race, and thus raised a constitutional issue under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"27, 35, 44, 50, 51, 52","3":"16, 25"}},{"t":"case","label":"Shelby County v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"op":4,"ar":1,"sum":"Holding the 2006 preclearance coverage formula unconstitutional.","sumSrc":"opinion","by":{"0":"73","1":"58","3":"32, 33","4":"41"}},{"t":"case","label":"Silver v. Diaz","cite":"522 U.S. 801","y":1997,"url":"https://supreme.justia.com/cases/federal/us/522/801/","sc":1,"by":{"0":"78"}},{"t":"case","label":"South Carolina v. Katzenbach","cite":"383 U.S. 301","y":1966,"id":"1965/22_orig","sc":1,"op":6,"ar":1,"sum":"Describing the limited issues presented.","sumSrc":"opinion","by":{"0":"72, 74","1":"4, 58","2":"4, 56","4":"41"}},{"t":"case","label":"Thornburg v. Gingles","cite":"478 U.S. 30","y":1986,"id":"1985/83-1968","sc":1,"op":18,"sum":"Explaining that the vote-dilution inquiry “is peculiarly dependent upon the facts of each case and requires an intensely local appraisal” (citation and internal quotation marks omitted).","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"55","3":"passim","4":"passim"}},{"t":"case","label":"United States v. Wong Kim Ark","cite":"169 U.S. 649","y":1898,"id":"1850-1900/169us649","sc":1,"sum":"Because Wong was born in the United States and his parents were not “employed in any diplomatic or official capacity under the Emperor of China,” the Citizenship Clause of the Fourteenth Amendment automatically makes him a U.S. citizen.","sumSrc":"Oyez","by":{"0":"78"}},{"t":"case","label":"Vieth v. Jubelirer","cite":"541 U.S. 267","y":2004,"id":"2003/02-1580","sc":1,"sum":"In a split decision that had no majority opinion, the Court decided not to intervene in this case because no appropriate judicial solution could be found. Justice Antonin Scalia, for a four-member plurality, wrote that the Court should declare all claims related to political (but not racial) gerrymandering nonjusticiable, meaning that courts could not hear them.","sumSrc":"Oyez","by":{"0":"40, 69","4":"18"}},{"t":"case","label":"Voinovich v. Quilter","cite":"507 U.S. 146","y":1993,"id":"1992/91-1618","sc":1,"op":8,"sum":"Pursuant to the Ohio Constitution's requirement that electoral districts for the state legislature be reapportioned every 10 years, appellant James Tilling drafted and the state apportionment board adopted in 1991 an apportionment plan that created several districts in which a majority of the population is a member of a specific minority group. Appellees, Democratic board members who voted against the plan and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 36, 43, 52","1":"passim","2":"27","3":"14, 30","4":"13, 15, 25"}},{"t":"case","label":"Wesch v. Hunt","cite":"785 F. Supp. 1491","y":1992,"court":"S.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./785/1491/","op":5,"by":{"0":"11","1":"15","2":"9","4":"32"}},{"t":"case","label":"Whitcomb v. Chavis","cite":"403 U.S. 124","y":1971,"id":"1970/92","sc":1,"ar":2,"sum":"The judgment is reversed and the case remanded. Pp. 140-170; 179-180. 305 F. Supp. 1364, reversed and remanded. WHITCOMB v. CHAVIS","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","2":"25","3":"11","4":"7"}},{"t":"case","label":"White v. Regester","cite":"412 U.S. 755","y":1973,"id":"1972/72-147","sc":1,"op":5,"ar":2,"sum":"In this litigation challenging the Texas 1970 legislative reapportionment scheme, a three-judge District Court held that the House plan, statewide, contained constitutionally impermissi]ile deviations from population equality, and that the multimember districts provided for Bexar and Dallas Counties invidiously discriminated against cognizable racial or ethnic groups. Though the entire plan was declared invalid, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"4, 25, 28","3":"3, 11, 30","4":"7, 11"}},{"t":"case","label":"White v. Weiser","cite":"412 U.S. 783","y":1973,"id":"1972/71-1623","sc":1,"op":2,"sum":"1. -Although the percentage deviations in \"S. B. 1 are smaller than those invalidated in Kirkpatrick v. Preisler, 394 U. S. 526, and Wells v. Rockefeller, 394 U. S. 542, they were not \"unavoidable\" and the districts were not as mathematically equal as reasonably possible. The argument that variances are justified if they necessarily result from the State's attempt to avoid fragmenting political subdivisions by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"61"}},{"t":"case","label":"Wis. Legislature v. Wis. Elections Comm’n","cite":"142 S. Ct. 1245","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/1245/","sc":1,"op":11,"sum":"Rejecting as constitutionally deficient the rationale that “there is now a sufficiently large and compact population of black residents to” justify creation of an additional majority-black district.","sumSrc":"brief:0","by":{"0":"passim","1":"7, 49","3":"passim","4":"passim"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"3","1":"57"}},{"t":"const","label":"Amendment XV","clauses":[["fifteenth-amendment","Fifteenth Amendment"]],"text":"The right of citizens of the United States to vote shall not be denied or abridged by the United States or by any State on account of race, color, or previous condition of servitude-- The Congress shall have power to enforce this article by appropriate legislation.","by":{"0":"passim","1":"57, 59","2":"56","3":"2, 32, 33"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2284","url":"https://www.law.cornell.edu/uscode/text/28/2284","subs":["(a)"],"stext":{"head":"§2284. Three-judge court; when required; composition; procedure","paras":[[0,"(a) A district court of three judges shall be convened when otherwise required by Act of Congress, or when an action is filed challenging the constitutionality of the apportionment of congressional districts or the apportionment of any statewide legislative body."],[0,"(b) In any action required to be heard and determined by a district court of three judges under subsection (a) of this section, the composition and procedure of the court shall be as follows:"],[0,"(1) Upon the filing of a request for three judges, the judge to whom the request is presented shall, unless he determines that three judges are not required, immediately notify the chief judge of the circuit, who shall designate two other judges, at least one of whom shall be a circuit judge. The judges so designated, and the judge to whom the request was presented, shall serve as members of the court to hear and determine the action or proceeding."],[0,"(2) If the action is against a State, or officer or agency thereof, at least five days' notice of hearing of the action shall be given by registered or certified mail to the Governor and attorney general of the State."],[0,"(3) A single judge may conduct all proceedings except the trial, and enter all orders permitted by the rules of civil procedure except as provided in this subsection. He may grant a temporary restraining order on a specific finding, based on evidence submitted, that specified irreparable damage will result if the order is not granted, which order, unless previously revoked by the district judge, shall remain in force only until the hearing and determination by the district court of three judges of an application for a preliminary injunction. A single judge shall not appoint a master, or order a reference, or hear and determine any application for a preliminary or permanent injunction or motion to vacate such an injunction, or enter judgment on the merits. Any action of a single judge may be reviewed by the full court at any time before final judgment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2284?type=usc&year=mostrecent&link-type=html"},"head":"§2284. Three-judge court; when required; composition; procedure","tname":"Judiciary and Judicial Procedure","by":{"0":"19","3":"6"}},{"t":"usc","label":"52 U.S.C. § 10301","url":"https://www.law.cornell.edu/uscode/text/52/10301","subs":["(a)","(b)"],"stext":{"head":"§10301. Denial or abridgement of right to vote on account of race or color through voting qualifications or prerequisites; establishment of violation","paras":[[0,"(a) No voting qualification or prerequisite to voting or standard, practice, or procedure shall be imposed or applied by any State or political subdivision in a manner which results in a denial or abridgement of the right of any citizen of the United States to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, as provided in subsection (b)."],[0,"(b) A violation of subsection (a) is established if, based on the totality of circumstances, it is shown that the political processes leading to nomination or election in the State or political subdivision are not equally open to participation by members of a class of citizens protected by subsection (a) in that its members have less opportunity than other members of the electorate to participate in the political process and to elect representatives of their choice. The extent to which members of a protected class have been elected to office in the State or political subdivision is one circumstance which may be considered: Provided, That nothing in this section establishes a right to have members of a protected class elected in numbers equal to their proportion in the population."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10301?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§10301. Denial or abridgement of right to vote on account of race or color through voting qualifications or prerequisites; establishment of violation","tname":"Voting and Elections","by":{"0":"passim, passim, passim","1":"passim","2":"23, 43, 54, 5, 54, 55, 1, 5, 20, 25, 26, 28, 40, 54","3":"1, 30, 30","4":"passim, passim"}},{"t":"law","label":"Pub. L. No. 89-110","url":"https://www.govinfo.gov/link/statute/79/437","by":{"0":"32, 33"}},{"t":"law","label":"Pub. L. No. 97-205","url":"https://www.govinfo.gov/link/statute/96/134","by":{"0":"33"}},{"t":"case","label":"Ala. Legis. Black Caucus v. Alabama","cite":"231 F. Supp. 3d 1026","y":2017,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/231/1026/","by":{"1":"12","2":"6, 7","4":"33"}},{"t":"case","label":"Allen v. City of Evergreen","cite":"2014 WL 12607819","y":2014,"court":"S.D. Ala. Jan. 13","by":{"1":"12"}},{"t":"case","label":"Anderson v. City of Bessemer","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"sum":"The Court of Appeals misapprehended and misapplied the clearlyerroneous standard and accordingly erred in denying petitioner relief under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29, 30","2":"36, 37"}},{"t":"case","label":"Ankenbrandt v. Richards","cite":"504 U.S. 689","y":1992,"id":"1991/91-367","sc":1,"sum":"Petitioner brought this suit on behalf of her daughters in the District Court, alleging federal jurisdiction based on the diversity-of-citizenship provision of 28 U. S. C. § 1332, and seeking monetary damages for alleged torts committed against the girls by their father and his female companion, the respondents here. The court granted respondents' motion to dismiss without prejudice, ruling in the alternative that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Camp v. Wesch","cite":"504 U.S. 902","y":1992,"url":"https://supreme.justia.com/cases/federal/us/504/902/","sc":1,"op":1,"by":{"1":"15"}},{"t":"case","label":"Chen v. City of Houston","cite":"206 F.3d 502","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/206/502/","op":8,"ar":2,"by":{"1":"37"}},{"t":"case","label":"Chisom v. Roemer","cite":"501 U.S. 380","y":1991,"id":"1990/90-757","sc":1,"op":3,"ar":1,"sum":"The Court determined that if Congress had that aim, it would have indicated this exclusion explicitly. Consequently, the Court favored a broad interpretation of the word \"representative\" in section 2 of the Voting Rights Act, considering it to encompass all winners of popular elections.","sumSrc":"Oyez","by":{"1":"4, 50, 51","2":"25","3":"3"}},{"t":"case","label":"City of Cleburne v. Cleburne Living Ctr., Inc.","cite":"473 U.S. 432","y":1985,"id":"1984/84-468","sc":1,"sum":"In a unanimous judgment, the Court held that the denial of the special use permit to Cleburne Living Centers, Inc. was premised on an irrational prejudice against the mentally retarded, and hence unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"59"}},{"t":"case","label":"City of Rome v. United States","cite":"446 U.S. 156","y":1980,"id":"1979/78-1840","sc":1,"op":12,"sum":"In 1966, appellant city of Rome, Ga., made certain changes in its electoral system, including provisions for majority rather than plurality vote for each of the nine members of the City Commission; for three numbered posts within each of the three (reduced from nine) wards; and for staggered terms for the commissioners and for members of the Board of Education from each ward; and a requirement that members of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"57, 58","3":"32"}},{"t":"case","label":"Davis v. Chiles","cite":"139 F.3d 1414","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/139/1414/","sum":"Rejecting racial predominance argument where defendant was “[un]able to identify a single traditional redistricting principle which [plaintiff’s] subdistricting scheme would violate”.","sumSrc":"brief:1","by":{"1":"31, 33, 34"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"1":"43","2":"41","3":"23"}},{"t":"case","label":"Jones v. Jefferson Cnty. Bd. of Educ.","cite":"2019 WL 7500528","y":2019,"court":"N.D. Ala. Dec. 16","by":{"1":"12"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"op":2,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"1":"passim","2":"21, 41, 42"}},{"t":"case","label":"Merrill v. Milligan","cite":"142 S. Ct. 879","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/879/","sc":1,"op":8,"ar":1,"by":{"1":"22","2":"19","4":"24"}},{"t":"case","label":"Nipper v. Smith","cite":"39 F.3d 1494","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1494/","sum":"Rejecting racial predominance argument where defendant was “[un]able to identify a single traditional redistricting principle which [plaintiff’s] subdistricting scheme would violate”.","sumSrc":"brief:1","by":{"1":"60"}},{"t":"case","label":"North Carolina v. Covington","cite":"138 S. Ct. 2548","y":2018,"id":"2017/17-1364","sc":1,"op":9,"sum":"A case in which the Court affirmed the district court’s order insofar as it provided a court-drawn remedy for Senate districts 21 and 28 and House districts 21 and 57, and reversed as to the court’s actions regarding the legislature’s redrawing of House districts in Wake and Mecklenburg Counties.","sumSrc":"Oyez","by":{"1":"54","2":"30"}},{"t":"case","label":"Oregon v. Mitchell","cite":"400 U.S. 112","y":1970,"id":"1970/43-orig","sc":1,"sum":"The Court held that Congress had the power to enact the amendments that changed the voting age for federal elections, abolish literary tests at the polling station, and abolish state residency requirements for presidential and vice presidential election. However, the Court held that lowering the voting age for state and local election was beyond Congressional purview.","sumSrc":"Oyez","by":{"1":"57"}},{"t":"case","label":"Reno v. Bossier Par. Sch. Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"sum":"The Court held that section 5 does not prohibit preclearance of a redistricting plan enacted with a discriminatory but nonretrogressive purpose. \"As we have repeatedly noted, in vote-dilution cases [section 5] prevents nothing but backsliding, and preclearance under [section 5] affirms nothing but the absence of backsliding,\" wrote Justice Scalia.","sumSrc":"Oyez","by":{"1":"44, 50","2":"35, 43, 55","4":"13, 14"}},{"t":"case","label":"Robinson v. Ardoin","cite":"37 F.4th 208","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/37/208/","sum":"Finding core retention analysis “has little value in evaluating whether the plaintiffs satisfied [§2’s] compactness requirement”.","sumSrc":"brief:1","by":{"1":"31, 34, 37","2":"44","3":"27, 34"}},{"t":"case","label":"Rogers v. Lodge","cite":"458 U.S. 613","y":1982,"id":"1981/80-2100","sc":1,"ar":1,"sum":"In a 6-to-3 decision, the Court held that the at-large system of elections in Burke County violated the Equal Protection Clause of the Fourteenth Amendment. The Court held that there was sufficient evidence to warrant the conclusion that the at-large system was operated as a purposeful device to further racial discrimination.","sumSrc":"Oyez","by":{"1":"28, 59","2":"20, 29, 57"}},{"t":"case","label":"Shelley v. Kraemer","cite":"334 U.S. 1","y":1948,"id":"1940-1955/334us1","sc":1,"sum":"The Court ruled that enforcement of racially restrictive covenants were a violation of the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"53"}},{"t":"case","label":"Stout ex rel. Stout v. Jefferson Cnty. Bd. of Educ.","cite":"882 F.3d 988","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/988/","by":{"1":"12"}},{"t":"case","label":"United States v. McGregor","cite":"824 F. Supp. 2d 1339","y":2011,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/824/1339/","by":{"1":"1, 10, 12","2":"7, 38","4":"34"}},{"t":"law","label":"Pub. L. No. 109-246","url":"https://www.govinfo.gov/link/plaw/109/public/246","by":{"1":"44","2":"42"}},{"t":"case","label":"Allen v. State Bd. of Elections","cite":"393 U.S. 544","y":1969,"id":"1968/3","sc":1,"sum":"The Supreme Court held that § 5 authorized a private right of action based on the remedial aims of the Voting Rights Act. The Court also interpreted the Act to provide that litigants bring these suits in their local district courts, and that three-judge district courts be convened (as was true at that time in constitutional challenges).","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Barnett v. City of Chicago","cite":"141 F.3d 699","court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/141/699/","by":{"2":"45"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Burton v. Hobbie","cite":"561 F. Supp. 1029","y":1983,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./561/1029/","by":{"2":"7","4":"33"}},{"t":"case","label":"Busbee v. Smith","cite":"549 F. Supp. 494","y":1982,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./549/494/","by":{"2":"39"}},{"t":"case","label":"Clark v. Calhoun Cnty.","cite":"88 F.3d 1393","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/88/1393/","by":{"2":"43"}},{"t":"case","label":"Cottier v. City of Martin","cite":"604 F.3d 553","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/604/553/","by":{"2":"28"}},{"t":"case","label":"Easley v. Cromartie","cite":"532 U.S. 234","y":2001,"id":"2000/99-1864","sc":1,"sum":"The Court held that the District Court's conclusion that the state violated the Equal Protection Clause in drawing the 1997 boundaries is based on clearly erroneous findings.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Flowers v. Mississippi","cite":"139 S. Ct. 2228","y":2019,"id":"2018/17-9572","sc":1,"sum":"The trial court at Flowers’ sixth murder trial committed clear error in concluding that the State’s peremptory strike of a particular black prospective juror was not motivated in substantial part by discriminatory intent.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"29, 38"}},{"t":"case","label":"Fusilier v. Landry","cite":"963 F.3d 447","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/447/","by":{"2":"30"}},{"t":"case","label":"FW/PBS, Inc. v. Dallas","cite":"493 U.S. 215","y":1990,"id":"1989/87-2012","sc":1,"sum":"The judgment is affirmed in part, reversed in part, and vacated in part, and the cases are remanded. 837 F. 2d 1298, affirmed in part, reversed in part, vacated in part, and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts III and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"Gomillion v. Lightfoot","cite":"364 U.S. 339","y":1960,"id":"1960/32","sc":1,"sum":"The unanimous Court held that the Alabama legislature violated the Fifteenth Amendment. Justice Frankfurter admitted that states are insulated from judicial review when they exercise power \"wholly within the domain of state interest.\" However, in this case, Alabama's representatives were unable to identify \"any countervailing municipal function\" the act was designed to serve.","sumSrc":"Oyez","by":{"2":"4, 53"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Johnson v. Hamrick","cite":"296 F.3d 1065","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/296/1065/","by":{"2":"28"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"2":"55"}},{"t":"case","label":"NAACP v. Fordice","cite":"252 F.3d 361","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/361/","by":{"2":"30"}},{"t":"case","label":"Nev. Dep’t of Hum. Res. v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Reno v. Bossier Par. Sch. Bd.","cite":"520 U.S. 471","y":1997,"id":"1996/95-1455","sc":1,"op":9,"sum":"The Court ruled that preclearance under ?5 of the Voting Rights Act of 1965 may not be denied solely on the basis that a covered jurisdiction's new voting \"standard, practice, or procedure\" violates ? 2 of the Act.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"sum":"The Court held that while a guilty plea could qualify as a predicate offense under the ACCA, courts may only look to the following when determining if that plea admitted to generic burglary: the terms of the charging document, the terms of a plea agreement, or a judicial record in which the defendant confirmed the factual basis for the plea (such as conversation between defendant and judge).","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Sims v. Amos","cite":"336 F. Supp. 924","y":1972,"url":"https://www.courtlistener.com/c/F.%20Supp./336/924/","by":{"2":"7"}},{"t":"case","label":"Sims v. Baggett","cite":"247 F. Supp. 96","y":1965,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./247/96/","by":{"2":"7"}},{"t":"case","label":"Stabler v. Thurston Cnty","cite":"129 F.3d 105","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/129/105/","by":{"2":"27"}},{"t":"case","label":"United States v. Hays","cite":"515 U.S. 737","y":1995,"id":"1994/94-558","sc":1,"op":19,"sum":"Explaining that race predominates when “the [mapmaker] subordinated traditional race-neutral districting principles . . . to racial considerations”.","sumSrc":"opinion","by":{"2":"46, 47"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"2":"22, 44"}},{"t":"case","label":"Veasey v. Abbott","cite":"830 F.3d 216","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/830/216/","by":{"2":"55"}},{"t":"case","label":"Village of Arlington Heights v. Metro. Hous. Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"op":2,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"usc","label":"52 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/52/10101","subs":["(e)"],"stext":{"head":"§10101. Voting rights","paras":[[0,"(a) Race, color, or previous condition not to affect right to vote; uniform standards for voting qualifications; errors or omissions from papers; literacy tests; agreements between Attorney General and State or local authorities; definitions"],[0,"(1) All citizens of the United States who are otherwise qualified by law to vote at any election by the people in any State, Territory, district, county, city, parish, township, school district, municipality, or other territorial subdivision, shall be entitled and allowed to vote at all such elections, without distinction of race, color, or previous condition of servitude; any constitution, law, custom, usage, or regulation of any State or Territory, or by or under its authority, to the contrary notwithstanding."],[0,"(2) No person acting under color of law shall—"],[1,"(A) in determining whether any individual is qualified under State law or laws to vote in any election, apply any standard, practice, or procedure different from the standards, practices, or procedures applied under such law or laws to other individuals within the same county, parish, or similar political subdivision who have been found by State officials to be qualified to vote;"],[1,"(B) deny the right of any individual to vote in any election because of an error or omission on any record or paper relating to any application, registration, or other act requisite to voting, if such error or omission is not material in determining whether such individual is qualified under State law to vote in such election; or"],[1,"(C) employ any literacy test as a qualification for voting in any election unless (i) such test is administered to each individual and is conducted wholly in writing, and (ii) a certified copy of the test and of the answers given by the individual is furnished to him within twenty-five days of the submission of his request made within the period of time during which records and papers are required to be retained and preserved pursuant to title III of the Civil Rights Act of 1960 [52 U.S.C. 20701 et seq.]: Provided, however, That the Attorney General may enter into agreements with appropriate State or local authorities that preparation, conduct, and maintenance of such tests in accordance with the provisions of applicable State or local law, including such special provisions as are necessary in the preparation, conduct, and maintenance of such tests for persons who are blind or otherwise physically handicapped, meet the purposes of this subparagraph and constitute compliance therewith."],[0,"(3) For purposes of this subsection—"],[1,"(A) the term \"vote\" shall have the same meaning as in subsection (e) of this section;"],[1,"(B) the phrase \"literacy test\" includes any test of the ability to read, write, understand, or interpret any matter."],[0,"(b) Intimidation, threats, or coercion"],[0,"No person, whether acting under color of law or otherwise, shall intimidate, threaten, coerce, or attempt to intimidate, threaten, or coerce any other person for the purpose of interfering with the right of such other person to vote or to vote as he may choose, or of causing such other person to vote for, or not to vote for, any candidate for the office of President, Vice President, presidential elector, Member of the Senate, or Member of the House of Representatives, Delegates or Commissioners from the Territories or possessions, at any general, special, or primary election held solely or in part for the purpose of selecting or electing any such candidate."],[0,"(c) Preventive relief; injunction; rebuttable literacy presumption; liability of United States for costs; State as party defendant"],[0,"Whenever any person has engaged or there are reasonable grounds to believe that any person is about to engage in any act or practice which would deprive any other person of any right or privilege secured by subsection (a) or (b), the Attorney General may institute for the United States, or in the name of the United States, a civil action or other proper proceeding for preventive relief, including an application for a permanent or temporary injunction, restraining order, or other order. If in any such proceeding literacy is a relevant fact there shall be a rebuttable presumption that any person who has not been adjudged an incompetent and who has completed the sixth grade in a public school in, or a private school accredited by, any State or territory, the District of Columbia, or the Commonwealth of Puerto Rico where instruction is carried on predominantly in the English language, possesses sufficient literacy, comprehension, and intelligence to vote in any election. In any proceeding hereunder the United States shall be liable for costs the same as a private person. Whenever, in a proceeding instituted under this subsection any official of a State or subdivision thereof is alleged to have committed any act or practice constituting a deprivation of any right or privilege secured by subsection (a), the act or practice shall also be deemed that of the State and the State may be joined as a party defendant and, if, prior to the institution of such proceeding, such official has resigned or has been relieved of his office and no successor has assumed such office, the proceeding may be instituted against the State."],[0,"(d) Jurisdiction; exhaustion of other remedies"],[0,"The district courts of the United States shall have jurisdiction of proceedings instituted pursuant to this section and shall exercise the same without regard to whether the party aggrieved shall have exhausted any administrative or other remedies that may be provided by law."],[0,"(e) Order qualifying person to vote; application; hearing; voting referees; transmittal of report and order; certificate of qualification; definitions"],[0,"In any proceeding instituted pursuant to subsection (c) in the event the court finds that any person has been deprived on account of race or color of any right or privilege secured by subsection (a), the court shall upon request of the Attorney General and after each party has been given notice and the opportunity to be heard make a finding whether such deprivation was or is pursuant to a pattern or practice. If the court finds such pattern or practice, any person of such race or color resident within the affected area shall, for one year and thereafter until the court subsequently finds that such pattern or practice has ceased, be entitled, upon his application therefor, to an order declaring him qualified to vote, upon proof that at any election or elections (1) he is qualified under State law to vote, and (2) he has since such finding by the court been (a) deprived of or denied under color of law the opportunity to register to vote or otherwise to qualify to vote, or (b) found not qualified to vote by any person acting under color of law. Such order shall be effective as to any election held within the longest period for which such applicant could have been registered or otherwise qualified under State law at which the applicant's qualifications would under State law entitle him to vote."],[0,"Notwithstanding any inconsistent provision of State law or the action of any State officer or court, an applicant so declared qualified to vote shall be permitted to vote in any such election. The Attorney General shall cause to be transmitted certified copies of such order to the appropriate election officers. The refusal by any such officer with notice of such order to permit any person so declared qualified to vote to vote at an appropriate election shall constitute contempt of court."],[0,"An application for an order pursuant to this subsection shall be heard within ten days, and the execution of any order disposing of such application shall not be stayed if the effect of such stay would be to delay the effectiveness of the order beyond the date of any election at which the applicant would otherwise be enabled to vote."],[0,"The court may appoint one or more persons who are qualified voters in the judicial district, to be known as voting referees, who shall subscribe to the oath of office required by section 3331 of title 5, to serve for such period as the court shall determine, to receive such applications and to take evidence and report to the court findings as to whether or not at any election or elections (1) any such applicant is qualified under State law to vote, and (2) he has since the finding by the court heretofore specified been (a) deprived of or denied under color of law the opportunity to register to vote or otherwise to qualify to vote, or (b) found not qualified to vote by any person acting under color of law. In a proceeding before a voting referee, the applicant shall be heard ex parte at such times and places as the court shall direct. His statement under oath shall be prima facie evidence as to his age, residence, and his prior efforts to register or otherwise qualify to vote. Where proof of literacy or an understanding of other subjects is required by valid provisions of State law, the answer of the applicant, if written, shall be included in such report to the court; if oral, it shall be taken down stenographically and a transcription included in such report to the court."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10101?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§10101. Voting rights","tname":"Voting and Elections","by":{"2":"55"}},{"t":"usc","label":"52 U.S.C. § 10304","url":"https://www.law.cornell.edu/uscode/text/52/10304","subs":["(a)","(b)"],"stext":{"head":"§10304. Alteration of voting qualifications; procedure and appeal; purpose or effect of diminishing the ability of citizens to elect their preferred candidates","paras":[[0,"(a) Whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the first sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1964, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the second sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1968, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the third sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1972, such State or subdivision may institute an action in the United States District Court for the District of Columbia for a declaratory judgment that such qualification, prerequisite, standard, practice, or procedure neither has the purpose nor will have the effect of denying or abridging the right to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, and unless and until the court enters such judgment no person shall be denied the right to vote for failure to comply with such qualification, prerequisite, standard, practice, or procedure: Provided, That such qualification, prerequisite, standard, practice, or procedure may be enforced without such proceeding if the qualification, prerequisite, standard, practice, or procedure has been submitted by the chief legal officer or other appropriate official of such State or subdivision to the Attorney General and the Attorney General has not interposed an objection within sixty days after such submission, or upon good cause shown, to facilitate an expedited approval within sixty days after such submission, the Attorney General has affirmatively indicated that such objection will not be made. Neither an affirmative indication by the Attorney General that no objection will be made, nor the Attorney General's failure to object, nor a declaratory judgment entered under this section shall bar a subsequent action to enjoin enforcement of such qualification, prerequisite, standard, practice, or procedure. In the event the Attorney General affirmatively indicates that no objection will be made within the sixty-day period following receipt of a submission, the Attorney General may reserve the right to reexamine the submission if additional information comes to his attention during the remainder of the sixty-day period which would otherwise require objection in accordance with this section. Any action under this section shall be heard and determined by a court of three judges in accordance with the provisions of section 2284 of title 28 and any appeal shall lie to the Supreme Court."],[0,"(b) Any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting that has the purpose of or will have the effect of diminishing the ability of any citizens of the United States on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, to elect their preferred candidates of choice denies or abridges the right to vote within the meaning of subsection (a) of this section."],[0,"(c) The term \"purpose\" in subsections (a) and (b) of this section shall include any discriminatory purpose."],[0,"(d) The purpose of subsection (b) of this section is to protect the ability of such citizens to elect their preferred candidates of choice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10304?type=usc&year=mostrecent&link-type=html"},"head":"§10304. Alteration of voting qualifications; procedure and appeal; purpose or effect of diminishing the ability of citizens to elect their preferred candidates","tname":"Voting and Elections","by":{"2":"55","3":"30"}},{"t":"case","label":"Evenwel v. Abbott","cite":"578 U.S. 54","y":2016,"id":"2015/14-940","sc":1,"sum":"The Court determined that the “one person, one vote” principle of the Equal Protection Clause allows a state to draw its legislative districts based on total population.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Katzenbach v. Morgan","cite":"384 U.S. 641","y":1966,"id":"1965/847","sc":1,"sum":"The Supreme Court held that Section 4(e) is a proper exercise of the powers granted to Congress. With Justice William J. Brennan writing for the majority, the Court reasoned that Congress exercised its powers consistent with those afforded it by Section 5 of the Fourteenth Amendment. The Court then concluded that the Supremacy Clause prevented the enforcement of the New York English literacy requirement.","sumSrc":"Oyez","by":{"3":"32"}},{"t":"case","label":"Lopez v. Monterey County","cite":"525 U.S. 266","y":1999,"id":"1998/97-1396","sc":1,"sum":"Announced by Justice Sandra Day O'Connor, the Court ruled that the county is covered by the Act's pre-clearance requirement, but the state was not. Justice O'Connor wrote, \"We conclude that the county is required to seek pre-clearance before implementing California laws that effect voting changes in that county.\".","sumSrc":"Oyez","by":{"3":"32"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"op":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"Presley v. Etowah County Comm’n","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"sum":"In a majority opinion authored by Justice Anthony M. Kennedy, the Court determined that section 5 of the Voting Rights Act covers only changes that directly relate to voting.","sumSrc":"Oyez","by":{"3":"30"}},{"t":"case","label":"Yick Wo v. Hopkins","cite":"118 U.S. 356","y":1886,"id":"1850-1900/118us356","sc":1,"sum":"The Court concluded that, despite the impartial wording of the law, its biased enforcement violated the Equal Protection Clause.","sumSrc":"Oyez","by":{"3":"2"}},{"t":"usc","label":"52 U.S.C. § 10308","url":"https://www.law.cornell.edu/uscode/text/52/10308","subs":["(d)"],"by":{"3":"1"}},{"t":"case","label":"Adarand Constructors, Inc. v. Pena","cite":"515 U.S. 200","y":1995,"id":"1994/93-1841","sc":1,"op":20,"ar":1,"sum":"Explaining that race predominates when “the [mapmaker] subordinated traditional race-neutral districting principles . . . to racial considerations”.","sumSrc":"opinion","by":{"4":"32"}},{"t":"case","label":"Banerian v. Benson","cite":"2022 WL 676001","y":2022,"court":"W.D. Mich. Mar. 4","by":{"4":"21, 22"}},{"t":"case","label":"Brentwood Acad. v. Tenn. Secondary Sch. Athletic Ass’n","cite":"531 U.S. 288","y":2001,"id":"2000/99-901","sc":1,"op":1,"sum":"The Court held that the pervasive entwinement of state school officials in the ostensibly private organization, which regulated school sports, and the state education board's acknowledgment of the organization, indicated that the organization is a state actor for civil rights purposes. \"The nominally private character of the Association is overborne by the pervasive entwinement of public institutions and public officials in its composition and workings, and there is no substantial reason to claim unfairness in applying constitutional standards to it,\" wrote Justice Souter for the majority.","sumSrc":"Oyez","by":{"4":"38"}},{"t":"case","label":"Chamber of Com. of U.S. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"sum":"The Court held that Arizona laws requiring employers to verify the employment eligibility of their employees through a federal database was not unconstitutional.","sumSrc":"Oyez","by":{"4":"9"}},{"t":"case","label":"City of Richmond v. J.A. Croson Co.","cite":"488 U.S. 469","y":1989,"id":"1988/87-998","sc":1,"sum":"In a 6-to-3 decision, the Court held that \"generalized assertions\" of past racial discrimination could not justify \"rigid\" racial quotas for the awarding of public contracts. Justice O'Connor's opinion noted that the 30 percent quota could not be tied to \"any injury suffered by anyone,\" and was an impermissible employment of a suspect classification.","sumSrc":"Oyez","by":{"4":"40"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"6"}},{"t":"case","label":"Gratz v. Bollinger","cite":"539 U.S. 244","y":2003,"id":"2002/02-516","sc":1,"sum":"The Court held that the University of Michigan's practice of favoring applicants of certain races in the admissions process violated the Fourteenth Amendment.","sumSrc":"Oyez","by":{"4":"31"}},{"t":"case","label":"Hays v. Louisiana","cite":"936 F. Supp. 360","y":1996,"court":"W.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp./936/360/","by":{"4":"26, 27"}},{"t":"case","label":"Jenkins v. Red Clay Consol. Sch. Dist. Bd. of Educ.","cite":"4 F.3d 1103","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/4/1103/","by":{"4":"15"}},{"t":"case","label":"Kirksey v. Bd. of Sup’rs of Hinds Cnty.","cite":"554 F.2d 139","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/554/139/","by":{"4":"7"}},{"t":"case","label":"McCulloch v. Maryland","cite":"4 Wheat. 316","y":1819,"url":"https://www.courtlistener.com/c/Wheat./4/316/","op":1,"by":{"4":"41"}},{"t":"case","label":"NAACP v. City of Niagara Falls","cite":"65 F.3d 1002","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/65/1002/","by":{"4":"15"}},{"t":"case","label":"Parents Involved in Cmty. Sch. v. Seattle Sch. Dist. No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"op":3,"sum":"By a 5-4 vote, the Court applied a \"strict scrutiny\" framework and found Jefferson County's enrollment plan unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"4":"13, 40"}},{"t":"case","label":"Robinson v. Ardoin","cite":"2022 WL 2012389","y":2022,"court":"M.D. La. June 6","sum":"Rejecting Louisiana’s congressional districting plan under §2 for “fail[ing] to create a second majority-Black district”.","sumSrc":"brief:4","by":{"4":"27"}},{"t":"case","label":"Tennessee v. Lane","cite":"541 U.S. 509","y":2004,"id":"2003/02-1667","sc":1,"ar":1,"sum":"In a 5-to-4 opinion written by Justice John Paul Stevens, the Court held that Congress had sufficiently demonstrated the problems faced by disabled persons who sought to exercise fundamental rights protected by the Due Process clause of the 14th Amendment (such as access to a court).","sumSrc":"Oyez","by":{"4":"41"}},{"t":"const","label":"Amendment XV, Section 1","clauses":[["fifteenth-amendment","Fifteenth Amendment"]],"text":"The right of citizens of the United States to vote shall not be denied or abridged by the United States or by any State on account of race, color, or previous condition of servitude--","by":{"4":"37"}}]};